define(["jquery"], function($) {
    var riskColors = {
        attention: "#f4c95d",
        medium: "#f0a34a",
        high: "#e76f51",
        critical: "#c44536",
        never: "#6f42c1"
    };

    var buildDonut = function() {
        var $donut = $("[data-region='risk-donut']");
        if (!$donut.length) {
            return;
        }

        var values = [];
        var total = 0;
        $donut.find("[data-risk]").each(function() {
            var count = parseInt($(this).attr("data-count"), 10) || 0;
            var risk = $(this).attr("data-risk");
            values.push({risk: risk, count: count});
            total += count;
        });

        if (!total) {
            return;
        }

        var cursor = 0;
        var parts = [];
        $.each(values, function(index, item) {
            if (!item.count) {
                return;
            }
            var start = cursor;
            cursor += (item.count / total) * 100;
            parts.push(riskColors[item.risk] + " " + start.toFixed(2) + "% " + cursor.toFixed(2) + "%");
        });
        $donut.css("background", "conic-gradient(" + parts.join(",") + ")");
    };

    var bindFilters = function() {
        var $search = $("[data-region='student-search']");
        var $risk = $("[data-region='risk-filter']");
        var $rows = $("[data-region='student-row']");
        var $count = $("[data-region='visible-count']");
        var $noResults = $("[data-region='no-results']");

        if (!$rows.length) {
            return;
        }

        var apply = function() {
            var query = ($search.val() || "").toString().toLowerCase().trim();
            var risk = ($risk.val() || "").toString();
            var visible = 0;

            $rows.each(function() {
                var $row = $(this);
                var search = ($row.attr("data-search") || "").toLowerCase();
                var rowRisk = $row.attr("data-risk") || "";
                var show = (!query || search.indexOf(query) !== -1) && (!risk || rowRisk === risk);
                $row.toggle(show);
                if (show) {
                    visible++;
                }
            });

            $count.text(visible);
            $noResults.prop("hidden", visible !== 0);
        };

        $search.on("input", apply);
        $risk.on("change", apply);
    };

    return {
        init: function() {
            buildDonut();
            bindFilters();
        }
    };
});
